// Unit tests for src/utils/keyboard-shortcuts.js.
//
// These tests do NOT use jsdom because the existing jsdom@30 install in
// this environment has a broken post-install (the IDL files were not
// generated by `npm run prepare`), which would prevent the tests from
// running. Instead we build a minimal DOM stub using Node's native
// `EventTarget` class.
//
// The dispatcher only touches a handful of DOM APIs:
//   - document.activeElement  (read once per dispatch)
//   - element.dispatchEvent   (synthesize keydown)
//   - document.addEventListener / removeEventListener
// and the events it cares about are `KeyboardEvent`-shaped: `key`,
// `shiftKey`, `ctrlKey`, `altKey`, `metaKey`, `target`, plus the
// bubbling/cancelable defaults. We reimplement just enough of
// KeyboardEvent on top of `Event` to exercise the dispatcher.
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
vi; // keep ts/lint quiet about the vitest namespace; spy helpers below use it.
import {
  isEditableElement,
  createChordTracker,
  createKeyboardDispatcher,
} from '../../src/utils/keyboard-shortcuts.js';

/* ---------------------------------------------------------------- *
 * Minimal DOM stub. Just enough to exercise the dispatcher.        *
 * ---------------------------------------------------------------- */

class FakeEvent extends Event {
  constructor(type, init = {}) {
    super(type, init);
    this._key = init.key ?? '';
    this._shift = !!init.shiftKey;
    this._ctrl = !!init.ctrlKey;
    this._alt = !!init.altKey;
    this._meta = !!init.metaKey;
    this._target = init.target ?? null;
    this._defaultPrevented = false;
  }
  get key() {
    return this._key;
  }
  get shiftKey() {
    return this._shift;
  }
  get ctrlKey() {
    return this._ctrl;
  }
  get altKey() {
    return this._alt;
  }
  get metaKey() {
    return this._meta;
  }
  get target() {
    return this._target;
  }
  preventDefault() {
    this._defaultPrevented = true;
  }
  get defaultPrevented() {
    return this._defaultPrevented;
  }
}

class FakeNode {
  constructor(tag = 'div') {
    this.tagName = tag.toUpperCase();
    this.children = [];
    this.parentNode = null;
    this._attrs = {};
    this._listeners = [];
    this._activeEl = false;
  }
  appendChild(child) {
    child.parentNode = this;
    this.children.push(child);
    return child;
  }
  setAttribute(k, v) {
    this._attrs[k] = v;
  }
  getAttribute(k) {
    return this._attrs[k] ?? null;
  }
  contains(other) {
    if (other === this) return true;
    for (const c of this.children) {
      if (c.contains(other)) return true;
    }
    return false;
  }
  focus() {
    doc.activeElement = this;
  }
  dispatchEvent(ev) {
    ev._target = this;
    for (const l of this._listeners) {
      l(ev);
      if (ev._stopped) break;
    }
    return true;
  }
  addEventListener(type, cb) {
    this._listeners.push(cb);
  }
  removeEventListener(type, cb) {
    this._listeners = this._listeners.filter((l) => l !== cb);
  }
}

function makeButton() {
  return new FakeNode('button');
}
function makeDiv() {
  return new FakeNode('div');
}
function makeInput() {
  const n = new FakeNode('input');
  n.type = 'text';
  return n;
}
function makeContenteditable() {
  const n = new FakeNode('div');
  n._attrs.contenteditable = 'true';
  return n;
}

class FakeDocument extends EventTarget {
  constructor() {
    super();
    this.body = makeNode('body');
    this.activeElement = null;
    this._captureListeners = [];
  }
  addEventListener(type, cb, opts) {
    // Mirror the DOM: any truthy 3rd arg OR `opts.capture === true`
    // marks the listener as capture-phase. The dispatcher uses the
    // 3-arg shorthand with `true`.
    const isCapture = opts === true || (opts && typeof opts === 'object' && opts.capture === true);
    if (isCapture) {
      this._captureListeners.push(cb);
    } else {
      super.addEventListener(type, cb, opts);
    }
  }
  removeEventListener(type, cb, opts) {
    if (opts === true || (opts && typeof opts === 'object' && opts.capture === true)) {
      this._captureListeners = this._captureListeners.filter((l) => l !== cb);
    } else {
      super.removeEventListener(type, cb, opts);
    }
  }
  // Test-helper: dispatch `ev` to all document-level capture
  // listeners. The dispatcher's listener attached with `capture:true`
  // is what we want to invoke.
  __fakeDispatch(ev) {
    for (const l of this._captureListeners) l(ev);
  }
}

const doc = new FakeDocument();

// The dispatcher's `attach()` short-circuits when `typeof document
// === 'undefined'`. In Node's `--environment=node` context `document`
// is not a global, so we hoist our fake onto globalThis.document so
// the dispatcher can install its listener. Our addEventListener /
// removeEventListener overrides forward to either the capture
// listener list (when opts === true) or to the standard EventTarget
// (for non-capture listeners, none of which the dispatcher installs).
globalThis.document = doc;

function makeNode(tag) {
  const n = new FakeNode(tag);
  return n;
}

// `EventTarget` natively supports add/remove EventListener with capture
// — our FakeDocument extends it. Override dispatchEvent on document to
// also fan-out to body (so when we dispatch on body, document capture
// listeners also fire).

class FakeKeyboardEvent extends FakeEvent {
  constructor(type, init) {
    super(type, { ...init, bubbles: init?.bubbles ?? true, cancelable: init?.cancelable ?? true });
  }
}

/* ---------------------------------------------------------------- *
 * Helpers for tests                                                 *
 * ---------------------------------------------------------------- */

/** Build a keydown event with sensible defaults; caller can override. */
function keyEvent(key, opts = {}) {
  return new FakeKeyboardEvent('keydown', {
    key,
    shiftKey: opts.shift || false,
    ctrlKey: opts.ctrl || false,
    altKey: opts.alt || false,
    metaKey: opts.meta || false,
  });
}

/** Fire a keydown on `target` (defaults to document.body).
 *  The dispatcher listens on `document` with `capture: true`, so we
 *  invoke the document capture listener(s) manually with the right
 *  target reference. */
function pressOn(target, key, opts = {}) {
  const ev = keyEvent(key, opts);
  ev._target = target;
  // Native EventTarget invokes capture listeners for events dispatched
  // on any descendant. Our fake forwards manually.
  if (typeof doc.__fakeDispatch === 'function') {
    doc.__fakeDispatch(ev);
  }
  return ev;
}

/** Fire a keydown on document.body (a common default). */
function press(key, opts = {}) {
  return pressOn(doc.body, key, opts);
}

beforeEach(() => {
  doc.body = makeNode('body');
  doc.activeElement = doc.body;
});

afterEach(() => {
  doc.body = makeNode('body');
  doc.activeElement = doc.body;
});

/* ---------------------------------------------------------------- *
 * isEditableElement                                                 *
 * ---------------------------------------------------------------- */

describe('isEditableElement', () => {
  it('returns false for null / undefined / non-elements', () => {
    expect(isEditableElement(null)).toBe(false);
    expect(isEditableElement(undefined)).toBe(false);
    expect(isEditableElement('input')).toBe(false);
    expect(isEditableElement(42)).toBe(false);
  });

  it('returns true for <input>', () => {
    const i = makeInput();
    expect(isEditableElement(i)).toBe(true);
  });

  it('returns true for <textarea>', () => {
    expect(isEditableElement(makeNode('textarea'))).toBe(true);
  });

  it('returns true for <select>', () => {
    expect(isEditableElement(makeNode('select'))).toBe(true);
  });

  it('returns true for contenteditable elements (true)', () => {
    expect(isEditableElement(makeContenteditable())).toBe(true);
  });

  it('returns true for contenteditable elements (plaintext-only)', () => {
    const d = makeDiv();
    d._attrs.contenteditable = 'plaintext-only';
    expect(isEditableElement(d)).toBe(true);
  });

  it('returns false for plain div / button / a', () => {
    expect(isEditableElement(makeDiv())).toBe(false);
    expect(isEditableElement(makeButton())).toBe(false);
    expect(isEditableElement(new FakeNode('a'))).toBe(false);
  });
});

/* ---------------------------------------------------------------- *
 * createChordTracker                                                *
 * ---------------------------------------------------------------- */

describe('createChordTracker', () => {
  it('first press returns "prefix"; pending is not armed yet', () => {
    const c = createChordTracker();
    expect(c.press('g')).toEqual({ kind: 'prefix', key: 'g' });
    expect(c.hasPending()).toBe(false);
  });

  it('arm() sets a pending prefix that expires at the timeout', () => {
    const c = createChordTracker(1000);
    c.press('g');
    c.arm('g');
    expect(c.hasPending()).toBe(true);
  });

  it('second press within timeout resolves as a chord and clears prefix', () => {
    const c = createChordTracker(1000);
    c.press('g');
    c.arm('g');
    expect(c.press('h')).toEqual({ kind: 'chord', key: 'h' });
    expect(c.hasPending()).toBe(false);
  });

  it('second press after timeout treats the press as a fresh prefix', () => {
    let clock = 0;
    const c = createChordTracker(20, () => clock);
    c.press('g');
    c.arm('g');
    clock = 30;
    expect(c.press('h')).toEqual({ kind: 'prefix', key: 'h' });
    expect(c.hasPending()).toBe(false);
  });

  it('clear() drops any pending prefix', () => {
    const c = createChordTracker(1000);
    c.press('g');
    c.arm('g');
    expect(c.hasPending()).toBe(true);
    c.clear();
    expect(c.hasPending()).toBe(false);
  });
});

/* ---------------------------------------------------------------- *
 * createKeyboardDispatcher                                          *
 * ---------------------------------------------------------------- */

describe('createKeyboardDispatcher', () => {
  it('attach() + detach() round-trips without throwing', () => {
    const d = createKeyboardDispatcher({});
    expect(() => d.attach()).not.toThrow();
    expect(() => press('a')).not.toThrow();
    expect(() => d.detach()).not.toThrow();
  });

  it('attach() is idempotent (safe to call twice)', () => {
    const d = createKeyboardDispatcher({});
    d.attach();
    d.attach();
    d.detach();
    expect(() => press('a')).not.toThrow();
  });

  it('"/" route invokes onSearch and preventDefaults', () => {
    const onSearch = vi.fn();
    const d = createKeyboardDispatcher({ onSearch });
    d.attach();
    const ev = press('/');
    expect(onSearch).toHaveBeenCalledTimes(1);
    expect(ev.defaultPrevented).toBe(true);
    d.detach();
  });

  it('"?" (Shift+/) invokes onHelp; plain "/" never invokes onHelp', () => {
    const onHelp = vi.fn();
    const d = createKeyboardDispatcher({ onHelp });
    d.attach();
    press('?', { shift: true });
    expect(onHelp).toHaveBeenCalledTimes(1);
    press('/');
    expect(onHelp).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('"/" while typing in an input does NOT invoke onSearch', () => {
    const input = makeInput();
    doc.body.appendChild(input);
    input.focus();
    const onSearch = vi.fn();
    const d = createKeyboardDispatcher({ onSearch });
    d.attach();
    pressOn(input, '/');
    expect(onSearch).not.toHaveBeenCalled();
    d.detach();
  });

  it('"?" while focused inside a contenteditable does NOT invoke onHelp', () => {
    const editable = makeContenteditable();
    doc.body.appendChild(editable);
    editable.focus();
    const onHelp = vi.fn();
    const d = createKeyboardDispatcher({ onHelp });
    d.attach();
    pressOn(editable, '?', { shift: true });
    expect(onHelp).not.toHaveBeenCalled();
    d.detach();
  });

  it('Ctrl+/ / Alt+/ / Meta+/ are ignored (browser-shortcut safety)', () => {
    const onSearch = vi.fn();
    const onHelp = vi.fn();
    const d = createKeyboardDispatcher({ onSearch, onHelp });
    d.attach();
    press('/', { ctrl: true });
    press('/', { alt: true });
    press('/', { meta: true });
    press('?', { shift: true, ctrl: true });
    expect(onSearch).not.toHaveBeenCalled();
    expect(onHelp).not.toHaveBeenCalled();
    d.detach();
  });

  it('Escape always invokes onEscape, even when an input is focused', () => {
    const input = makeInput();
    doc.body.appendChild(input);
    input.focus();
    const onEscape = vi.fn();
    const d = createKeyboardDispatcher({ onEscape });
    d.attach();
    press('Escape');
    expect(onEscape).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('"s" invokes onSave when body is active; not when input is focused', () => {
    const onSave = vi.fn();
    const d = createKeyboardDispatcher({ onSave });
    d.attach();
    press('s');
    expect(onSave).toHaveBeenCalledTimes(1);
    onSave.mockClear();

    const input = makeInput();
    doc.body.appendChild(input);
    input.focus();
    pressOn(input, 's');
    expect(onSave).not.toHaveBeenCalled();
    d.detach();
  });

  it('two-key chord "g h" routes to onGoHome', () => {
    const onGoHome = vi.fn();
    const d = createKeyboardDispatcher({ onGoHome });
    d.attach();
    press('g');
    press('h');
    expect(onGoHome).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('two-key chord "g s" routes to onGoSaved', () => {
    const onGoSaved = vi.fn();
    const d = createKeyboardDispatcher({ onGoSaved });
    d.attach();
    press('g');
    press('s');
    expect(onGoSaved).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('two-key chord "g p" routes to onGoPlanner', () => {
    const onGoPlanner = vi.fn();
    const d = createKeyboardDispatcher({ onGoPlanner });
    d.attach();
    press('g');
    press('p');
    expect(onGoPlanner).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('two-key chord "g n" routes to onGoNearby', () => {
    const onGoNearby = vi.fn();
    const d = createKeyboardDispatcher({ onGoNearby });
    d.attach();
    press('g');
    press('n');
    expect(onGoNearby).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('chord with non-handler second key (e.g. "g x") fires neither handler', () => {
    const onGoHome = vi.fn();
    const onGoSaved = vi.fn();
    const d = createKeyboardDispatcher({ onGoHome, onGoSaved });
    d.attach();
    press('g');
    press('x');
    expect(onGoHome).not.toHaveBeenCalled();
    expect(onGoSaved).not.toHaveBeenCalled();
    d.detach();
  });

  it('chord expires: pressing "g" then waiting >1s then "h" does NOT invoke onGoHome', () => {
    // Inject a fake monotonic clock directly into the dispatcher so
    // we don't have to fight vitest's useFakeTimers semantics for
    // performance.now. The factory stores the clock at construct
    // time; advance it manually to simulate >1s elapsed between
    // presses.
    let clock = 0;
    const onGoHome = vi.fn();
    const d = createKeyboardDispatcher({ onGoHome }, { chordTimeoutMs: 1000, now: () => clock });
    d.attach();
    press('g');
    clock = 1100; // jump past the chord timeout
    press('h');
    expect(onGoHome).not.toHaveBeenCalled();
    d.detach();
  });

  it('chord resets when an unrelated single key is pressed between g and h', () => {
    const onGoHome = vi.fn();
    const d = createKeyboardDispatcher({ onGoHome });
    d.attach();
    press('g');
    // 'a' is a non-chord single key, but our dispatcher ignores it (no
    // handler). It does, however, clear the chord tracker. Then
    // pressing 'g' arms again, and 'h' resolves.
    press('a');
    press('g');
    press('h');
    expect(onGoHome).toHaveBeenCalledTimes(1);
    d.detach();
  });

  it('"G" (uppercase, Shift) does not start a chord', () => {
    const onGoHome = vi.fn();
    const d = createKeyboardDispatcher({ onGoHome });
    d.attach();
    press('G', { shift: true });
    press('h');
    expect(onGoHome).not.toHaveBeenCalled();
    d.detach();
  });

  it('detach() removes listener: post-detach keypress is a no-op', () => {
    const onSearch = vi.fn();
    const d = createKeyboardDispatcher({ onSearch });
    d.attach();
    d.detach();
    press('/');
    expect(onSearch).not.toHaveBeenCalled();
  });

  it('multi-character keys (Tab, ArrowUp, etc.) are ignored', () => {
    const onSearch = vi.fn();
    const d = createKeyboardDispatcher({ onSearch });
    d.attach();
    press('Tab');
    press('Enter');
    press('ArrowUp');
    expect(onSearch).not.toHaveBeenCalled();
    d.detach();
  });
});
